settings.liquid:
{% assign has_coming_soon = false %}
{% assign has_back_soon = false %}
{% assign has_restock = false %}
{% assign has_black_friday_restock = false %}
{% assign has_launch = false %}
{% assign restock_date = "" %}
{% assign launch_date = "" %}
{% assign black_friday_launch_date = false %}

{% for tag in product.tags %}
    {% if tag == "__label:COMING SOON" %}
        {% assign has_coming_soon = true %}
    {% elsif tag == "__label:BACK SOON" %}
        {% assign has_back_soon = true %}
    {% elsif tag == "__label:RESTOCKS BLACK FRIDAY" %}
        {% assign has_black_friday_restock = true %}
    {% elsif tag contains "__label:RESTOCKS" %}
        {% assign has_restock = true %}
        {% assign restock_date = tag | remove: "__label:RESTOCKS " %}
    {% elsif tag == "__label:LAUNCHES BLACK FRIDAY" %}
        {% assign black_friday_launch_date = true %}
    {% elsif tag contains "__label:LAUNCHES" %}
        {% assign has_launch = true %}
        {% assign launch_date = tag | remove: "__label:LAUNCHES " %}
    {% endif %}
{% endfor %}

{% assign in_best_sellers = false %}
{% for collection in product.collections %}
    {% if collection.handle == 'best-sellers' %}
        {% assign in_best_sellers = true %}
    {% endif %}
{% endfor %}

{% unless has_back_soon or has_coming_soon or has_restock or has_launch or has_black_friday_restock or black_friday_launch_date %}
    {% unless product.title contains "Arcurva" %}
        {% if in_best_sellers %}
            {% unless product.tags contains "sale" %}
               <p><img src="https://cdn.shopify.com/s/files/1/0780/3843/files/icons8-price_09b4ad75-7e3d-4169-b74b-25d45d330242.svg?v=1721817633">&nbsp;25% off two or more bestsellers code: BEST</p>                
               <b>Early November Offer: 20% off this product code NOVFIND (Last Chance)</b>
            {% endunless %}
        {% else %}
            {% unless product.tags contains "sale" %}
                <b>Early November Offer: 20% off this product code NOVFIND (Last Chance)</b>
            {% endunless %}
        {% endif %}
    {% endunless %}

    {% if product.tags contains 'sale' %}
        <b>Extra 10% off sale code SALE10</b>
    {% endif %}
{% endunless %}

{% if has_coming_soon %}
    <b>Coming Soon</b>
{% elsif has_back_soon %}
    <b>Back in stock soon, sign up for restock notifications below </b>
{% elsif black_friday_launch_date %}
    <b>Launches 29.11.24 00:00 AM GMT</b>
{% elsif has_launch %}
    <b>Launches {{ launch_date }} 8PM</b>
{% elsif has_black_friday_restock %}
    <b>Restocks 29.11.24 00:00 AM GMT</b>
{% elsif has_restock %}
    <b>Restocks {{ restock_date }} 8PM</b>
{% endif %}

{% if product.variants[0].inventory_quantity > 0 %}
  {% for tag in product.tags %}
    {% if tag == 'pre-order' and product.variants[0].inventory_quantity < 11 %}
      <div class="instock-pulse">
        <span class="icon--pulsing"></span>
        <span>Available for pre order, {{ product.variants[0].inventory_quantity }} left </span>
      </div>
    {% elsif tag == 'pre-order' %}
      <div class="instock-pulse">
        <span class="icon--pulsing"></span>
        <span>Available for pre order</span>
      </div>
    {% endif %}
  {% endfor %}

  {% unless product.tags contains 'pre-order' %}
    {% if product.available and product.variants[0].inventory_quantity < 11 %}
{% unless product.tags contains 'PF' %}
      <div class="instock-pulse">
        <span class="icon--pulsing"></span>
        <span><b>In stock</b> and ready to ship, <b>{{ product.variants[0].inventory_quantity }} left </b></span>
      </div>
{% else %}
<div class="instock-pulse">
        <span class="icon--pulsing"></span>
        <span>In stock and ready to ship, <b>{{ product.variants[0].inventory_quantity }} left </b></span>
      </div>
{% endunless %}
    {% else %}
{% unless product.tags contains 'PF' %}
      <div class="instock-pulse">
        <span class="icon--pulsing"></span>
        <span><b>In stock</b> and ready to ship</span>
{% else %}
      <div class="instock-pulse">
        <span class="icon--pulsing"></span>
        <span><b>In stock</b> and ready to ship</span>
{% endunless %}
      </div>
    {% endif %}
  {% endunless %}

  <style>
    {% if product.available %}

        .instock-pulse {
          display: flex;
          flex-wrap: nowrap;
          align-items: center;          margin: 15px 0 0;
        }

        .icon--pulsing {
          position: relative;
          width: 20px;
          height: 20px;
          margin-right: 10px;
        }

        .icon--pulsing:after,
        .icon--pulsing:before {
            background: #54c63a;
            width: 10px;
            height: 10px;
            border-radius: 10px;
            position: absolute;
            left: 0;
            top: 0;
            content: "";
            margin: 5px;
        }

        @keyframes inventory-pulse{
          0%{
            opacity:0.5;
          }
          to{
            transform:scale(2.5);
            opacity:0;
          }
        }
    {% endif %}
    {% if product.variants[0].inventory_quantity >= 11 %}

        .icon--pulsing:before {
            animation: inventory-pulse 2.5s linear infinite;
        }

        {% elsif product.variants[0].inventory_quantity < 11 and product.variants[0].inventory_quantity > 1 %}

        .icon--pulsing:before {
            animation: inventory-pulse 1.5s linear infinite;
        }
{% else %}

.icon--pulsing:before {
            animation: inventory-pulse 1s linear infinite;
        }
    {% endif %}
  </style>
{% endif %}
